func TestCheckedInGuideMatchesInstallerPreview(t *testing.T) {
	repo, err := filepath.Abs(filepath.Join("..", ".."))
	if err != nil {
		t.Fatal(err)
	}
	want, err := os.ReadFile(filepath.Join(repo, ".entire", "agent-guide.md"))
	if err != nil {
